//go:build linux

package sandbox

import (
	"fmt"
	"unsafe"

	"golang.org/x/sys/unix"
)

func bpfStmt(code uint16, k uint32) unix.SockFilter {
	return unix.SockFilter{Code: code, K: k}
}

func bpfJump(code uint16, k uint32, jt, jf uint8) unix.SockFilter {
	return unix.SockFilter{Code: code, Jt: jt, Jf: jf, K: k}
}

const seccompRetLog uint32 = 0x7ffc0000

// SeccompFilterOptions configures the cBPF syscall filter generated by BuildSeccompFilter.
type SeccompFilterOptions struct {
	BlockNetwork bool // Block AF_INET, AF_INET6, AF_PACKET, and AF_NETLINK socket creation
	NoExec       bool // Block SYS_EXECVE and SYS_EXECVEAT subprocess execution
	AuditLog     bool // Return SECCOMP_RET_LOG instead of SECCOMP_RET_ERRNO|EPERM for audit testing
}

// BuildNetworkFilter returns a classic BPF (cBPF) filter with network isolation
// and process/IPC boundary hardening enabled.
func BuildNetworkFilter() ([]unix.SockFilter, error) {
	return BuildSeccompFilter(SeccompFilterOptions{
		BlockNetwork: true,
	})
}

// BuildSeccompFilter constructs a classic BPF (cBPF) filter enforcing:
//  1. Architecture validation against auditArch (mismatch returns EINVAL).
//  2. Always-on process memory protection: blocks SYS_PTRACE, SYS_PROCESS_VM_READV,
//     and SYS_PROCESS_VM_WRITEV.
//  3. Always-on System V IPC isolation: blocks SYS_SHMGET, SYS_SHMAT, SYS_SHMDT,
//     SYS_SHMCTL, SYS_SEMGET, SYS_SEMOP, SYS_SEMTIMEDOP, SYS_SEMCTL, SYS_MSGGET,
//     SYS_MSGSND, SYS_MSGRCV, and SYS_MSGCTL.
//  4. Always-on signal scoping: intercepts SYS_KILL, permitting signals only to
//     the current process group (pid == 0) and rejecting external host PIDs (pid != 0).
//     SYS_TGKILL and SYS_TKILL remain permitted for Go runtime goroutine preemption.
//  5. Optional subprocess execution lockdown (opts.NoExec): blocks SYS_EXECVE and SYS_EXECVEAT.
//  6. Optional network socket lockdown (opts.BlockNetwork): intercepts SYS_SOCKET to block
//     AF_INET, AF_INET6, AF_PACKET, and AF_NETLINK while permitting AF_UNIX.
func BuildSeccompFilter(opts SeccompFilterOptions) ([]unix.SockFilter, error) {
	if !isSupportedArch {
		return nil, errUnsupportedArch
	}

	deniedSyscalls := []uint32{
		// Process memory tampering
		uint32(unix.SYS_PTRACE),
		uint32(unix.SYS_PROCESS_VM_READV),
		uint32(unix.SYS_PROCESS_VM_WRITEV),
		// System V IPC shared memory, semaphores, and message queues
		uint32(unix.SYS_SHMGET),
		uint32(unix.SYS_SHMAT),
		uint32(unix.SYS_SHMDT),
		uint32(unix.SYS_SHMCTL),
		uint32(unix.SYS_SEMGET),
		uint32(unix.SYS_SEMOP),
		uint32(unix.SYS_SEMTIMEDOP),
		uint32(unix.SYS_SEMCTL),
		uint32(unix.SYS_MSGGET),
		uint32(unix.SYS_MSGSND),
		uint32(unix.SYS_MSGRCV),
		uint32(unix.SYS_MSGCTL),
	}

	if opts.NoExec {
		deniedSyscalls = append(deniedSyscalls,
			uint32(unix.SYS_EXECVE),
			uint32(unix.SYS_EXECVEAT),
		)
	}

	// Calculate total instruction count:
	// - 4 header instructions (load arch, jeq arch, ret einval, load syscall nr)
	// - len(deniedSyscalls) single-instruction checks
	// - 3 instructions for SYS_KILL pid == 0 scoping
	// - 6 instructions for SYS_SOCKET domain filtering (if opts.BlockNetwork)
	// - 2 terminal instructions: [idxAllow] RET_ALLOW, [idxDeny] RET_DENY
	totalLen := 4 + len(deniedSyscalls) + 3 + 2
	if opts.BlockNetwork {
		totalLen += 6
	}
	idxAllow := totalLen - 2
	idxDeny := totalLen - 1

	filter := make([]unix.SockFilter, 0, totalLen)

	// [0] Load architecture: seccomp_data.arch (offset 4)
	filter = append(filter, bpfStmt(unix.BPF_LD|unix.BPF_W|unix.BPF_ABS, 4))
	// [1] If arch == auditArch, continue to [3], else reject at [2]
	filter = append(filter, bpfJump(unix.BPF_JMP|unix.BPF_JEQ|unix.BPF_K, auditArch, 1, 0))
	// [2] Architecture mismatch -> return EINVAL
	filter = append(filter, bpfStmt(unix.BPF_RET|unix.BPF_K, unix.SECCOMP_RET_ERRNO|uint32(unix.EINVAL)))
	// [3] Load syscall number: seccomp_data.nr (offset 0)
	filter = append(filter, bpfStmt(unix.BPF_LD|unix.BPF_W|unix.BPF_ABS, 0))

	// Unconditionally blocked syscalls -> jump to idxDeny on match
	for _, sysNr := range deniedSyscalls {
		cur := len(filter)
		jt := uint8(idxDeny - (cur + 1))
		filter = append(filter, bpfJump(unix.BPF_JMP|unix.BPF_JEQ|unix.BPF_K, sysNr, jt, 0))
	}

	// SYS_KILL scoping: allow pid == 0 (own process group), deny pid != 0
	filter = append(filter, bpfJump(unix.BPF_JMP|unix.BPF_JEQ|unix.BPF_K, uint32(unix.SYS_KILL), 0, 2))
	filter = append(filter, bpfStmt(unix.BPF_LD|unix.BPF_W|unix.BPF_ABS, 16))
	{
		cur := len(filter)
		jtAllow := uint8(idxAllow - (cur + 1))
		jfDeny := uint8(idxDeny - (cur + 1))
		filter = append(filter, bpfJump(unix.BPF_JMP|unix.BPF_JEQ|unix.BPF_K, 0, jtAllow, jfDeny))
	}

	// Optional SYS_SOCKET domain filtering
	if opts.BlockNetwork {
		cur := len(filter)
		jfAllow := uint8(idxAllow - (cur + 1))
		filter = append(filter, bpfJump(unix.BPF_JMP|unix.BPF_JEQ|unix.BPF_K, uint32(unix.SYS_SOCKET), 0, jfAllow))
		filter = append(filter, bpfStmt(unix.BPF_LD|unix.BPF_W|unix.BPF_ABS, 16))

		domains := []uint32{
			unix.AF_INET,
			unix.AF_INET6,
			unix.AF_PACKET,
			unix.AF_NETLINK,
		}
		for _, dom := range domains {
			c := len(filter)
			jtDeny := uint8(idxDeny - (c + 1))
			filter = append(filter, bpfJump(unix.BPF_JMP|unix.BPF_JEQ|unix.BPF_K, dom, jtDeny, 0))
		}
	}

	// [idxAllow] Default / Allowed operation -> return ALLOW
	filter = append(filter, bpfStmt(unix.BPF_RET|unix.BPF_K, unix.SECCOMP_RET_ALLOW))

	// [idxDeny] Blocked operation -> return EPERM (or SECCOMP_RET_LOG if AuditLog is enabled)
	denyAction := uint32(unix.SECCOMP_RET_ERRNO) | uint32(unix.EPERM)
	if opts.AuditLog {
		denyAction = seccompRetLog
	}
	filter = append(filter, bpfStmt(unix.BPF_RET|unix.BPF_K, denyAction))

	return filter, nil
}

// ApplySeccompFilter installs the BPF filter on the current process and all future
// threads using PR_SET_NO_NEW_PRIVS and seccomp(SECCOMP_SET_MODE_FILTER, SECCOMP_FILTER_FLAG_TSYNC).
// If the seccomp(2) syscall returns ENOSYS, it falls back to prctl(PR_SET_SECCOMP).
func ApplySeccompFilter(filter []unix.SockFilter) error {
	if len(filter) == 0 {
		return nil
	}

	prog := unix.SockFprog{
		Len:    uint16(len(filter)),
		Filter: &filter[0],
	}

	// 1. Enforce no new privileges so unprivileged processes can attach seccomp filters
	if err := unix.Prctl(unix.PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0); err != nil {
		return fmt.Errorf("sandbox: prctl(PR_SET_NO_NEW_PRIVS) failed: %w", err)
	}

	// 2. Attach filter with TSYNC (thread synchronization) across all Go runtime OS threads
	_, _, err := unix.Syscall(
		unix.SYS_SECCOMP,
		unix.SECCOMP_SET_MODE_FILTER,
		unix.SECCOMP_FILTER_FLAG_TSYNC,
		uintptr(unsafe.Pointer(&prog)),
	)
	if err == 0 {
		return nil
	}

	// If seccomp(2) syscall is not available (kernels < 3.17), fallback to prctl
	if err == unix.ENOSYS {
		if prctlErr := unix.Prctl(unix.PR_SET_SECCOMP, unix.SECCOMP_MODE_FILTER, uintptr(unsafe.Pointer(&prog)), 0, 0); prctlErr != nil {
			return fmt.Errorf("sandbox: prctl(PR_SET_SECCOMP) fallback failed: %w", prctlErr)
		}
		return nil
	}

	return fmt.Errorf("sandbox: seccomp(SECCOMP_FILTER_FLAG_TSYNC) failed: %w", err)
}
